import 'package:flutter/material.dart';
import '../core/api_client.dart';

class ProductsScreen extends StatelessWidget { const ProductsScreen({super.key}); @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Products & Inventory'), actions: [IconButton(onPressed: () {}, icon: const Icon(Icons.add))]), body: FutureBuilder<Map<String, dynamic>>(future: ApiClient().products(), builder: (_, snapshot) { if (snapshot.connectionState != ConnectionState.done) return const Center(child: CircularProgressIndicator()); final items = ((snapshot.data?['data'] as Map<String, dynamic>?)?['data'] as List<dynamic>? ?? []); if (items.isEmpty) return const _Empty(); return ListView.separated(padding: const EdgeInsets.all(16), itemCount: items.length, separatorBuilder: (_, __) => const SizedBox(height: 10), itemBuilder: (_, i) { final item = items[i] as Map<String, dynamic>; return Card(child: ListTile(leading: const CircleAvatar(child: Icon(Icons.inventory_2_outlined)), title: Text(item['name']?.toString() ?? 'Product'), subtitle: Text('₹${item['sale_price'] ?? item['price'] ?? 0} • Stock ${item['stock_quantity'] ?? 0}'), trailing: Switch(value: item['is_active'] == true, onChanged: null)); }); })); }
class _Empty extends StatelessWidget { const _Empty(); @override Widget build(BuildContext context) => Center(child: Padding(padding: const EdgeInsets.all(28), child: Column(mainAxisSize: MainAxisSize.min, children: [const Icon(Icons.inventory_2_outlined, size: 72), const SizedBox(height: 14), Text('No products yet', style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.bold)), const SizedBox(height: 8), const Text('Add products after your business is approved.'), const SizedBox(height: 18), ElevatedButton.icon(onPressed: () {}, icon: const Icon(Icons.add), label: const Text('Add Product'))]))); }

